using MatPlotLibNet.Fidelity;
using MatPlotLibNet.Models;
using MatPlotLibNet.Styling;

namespace MatPlotLibNet.Tests.Fidelity.Charts;

/// <summary>v1.7.0 axis features (broken-axis, symlog) compared against matplotlib.
/// Reference fixtures generated by tools/mpl_reference/generate.py:
///   python generate.py --chart broken_y symlog
/// </summary>
public class AxisFeaturesFidelityTests : FidelityTest
{
    [Theory]
    [FidelityRows]
    // Measured on Windows and in the noble container: classic RMS 8.46 / 7.94, SSIM 0.9970 / 0.9968, colour distance 0.38 / 0; v2 RMS
    // 11.87 / 10.81, SSIM 0.9950 / 0.9951, colour distance 0 on both.
    [FidelityTolerance(Rms = 10, Ssim = 0.98, DeltaE = 2, V2Rms = 13, V2Ssim = 0.98, V2DeltaE = 1)]
    public void BrokenY_MatchesMatplotlib(string themeId)
    {
        // Data with low values 0..18 and high values 100..118, shown from 0 to 125 with 25..85 cut out. The reference is matplotlib's
        // broken-axis recipe (two stacked subplots, 85..125 over 0..25, a diagonal at each corner of the cut), which the library draws
        // under the matplotlib themes: the parts a GridSpec gap apart, each with its own ticks and spines, the recipe's diagonals for a
        // straight break.
        double[] x = Enumerable.Range(0, 20).Select(i => (double)i).ToArray();
        double[] y = x.Select(v => v < 10 ? v * 2 : v * 2 + 80).ToArray();

        var figure = FidelityFigure(themeId)
            .AddSubPlot(1, 1, 1, ax => ax
                .WithTitle("Broken Y-Axis")
                .Plot(x, y, s => s.Label = "Data")
                .SetYLim(0, 125)                              // the reference's set_ylim(0, 25) and set_ylim(85, 125)
                .WithYBreak(25, 85, BreakStyle.Straight)      // the recipe's "//" across the cut
                .SetXLabel("x")
                .WithLegend(LegendPosition.UpperLeft))
            .Build();

        AssertFidelity(figure, "broken_y");
    }

    [Theory]
    [FidelityRows]
    [FidelityTolerance(Rms = 21, Ssim = 0.94, DeltaE = 3, V2Rms = 20, V2Ssim = 0.91, V2DeltaE = 2)]
    public void Symlog_MatchesMatplotlib(string themeId)
    {
        // Cubic data x ∈ [-50, 50] spanning ±125000, symlog Y with linthresh=100.
        double[] x = Enumerable.Range(-50, 101).Select(i => (double)i).ToArray();
        double[] y = x.Select(v => v * v * v).ToArray();

        var figure = FidelityFigure(themeId)
            .AddSubPlot(1, 1, 1, ax => ax
                .WithTitle("Symlog Y-Axis — x³")
                .Plot(x, y, s => s.Label = "x³")
                .WithSymlogYScale(linthresh: 100)
                .SetXLabel("x")
                .SetYLabel("x³ (symlog, linthresh=100)")
                .WithLegend(LegendPosition.UpperLeft))
            .Build();

        AssertFidelity(figure, "symlog");
    }
}
